cmsis-pack-trace-snippet.debugvars:
// ETR
__var ETR___INSTANCE_INDEX___ADDRESS           = 0x00000000;
__var ETR___INSTANCE_INDEX___AP                = 0x00000000;
__var ETR___INSTANCE_INDEX___SYNCCNT           = 0xA;
__var ETR___INSTANCE_INDEX___TRIGGER_COUNT     = 0x0;
__var ETR___INSTANCE_INDEX___BUFFER_ADDRESS    = 0x00000000;
__var ETR___INSTANCE_INDEX___BUFFER_ADDRESS_HI = 0x00000000;
__var ETR___INSTANCE_INDEX___BUFFER_SIZE       = 0x00000000;
__var ETR___INSTANCE_INDEX___AXI_CTL           = 0x00000000; // [19:16]: RCACHE encoding
                                          // [11:8]: WrBurstLen
                                          // [5:2]: WCACHE encoding
                                          // [1]: Secure Access
                                          // [0]: Privileged Access
__var ETR___INSTANCE_INDEX___AXI_CTL1          = 0x00020000; // [27:16]: tlbXlateSlots
                                          // [7:6]: stashMode
                                          // [4:0]: tlbLimit

sequence.block:
// Helper variables
__var savedAP = __ap;
__var ffcrValue = 0x00000000;
__var etrStatus = 0x00000000;

Message(0, "Begin CS_ETR___INSTANCE_INDEX___Configure_CircularBuffer @0x%08X, AP 0x%08X", ETR___INSTANCE_INDEX___ADDRESS, ETR___INSTANCE_INDEX___AP);
__ap = ETR___INSTANCE_INDEX___AP;                                                           // Set AP

// Configure ETR for circular-buffer trace capture.
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);                                // Disable ETR before configuring
etrStatus = Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x00C);

// Helper variables
__var ffcrValue = 0x00000000;
__var savedAP = __ap;

Message(0, "Begin CS_ETR___INSTANCE_INDEX___Capture_CircularBuffer @0x%08X, AP 0x%08X", ETR___INSTANCE_INDEX___ADDRESS, ETR___INSTANCE_INDEX___AP);

__ap = ETR___INSTANCE_INDEX___AP;                                                           // Set AP
ffcrValue  = Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue |= 0x00000003;                                                                    // FFCR: Enable Formatter and Trigger Insertion
ffcrValue |= 0x00000400;                                                                    // FFCR: Insert trigger marker on flush completion (TrigFl)
ffcrValue |= 0x00001020;                                                                    // Flush and Stop Formatter on Trigger (FOnTrig + StopFl)
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x01C, ETR___INSTANCE_INDEX___TRIGGER_COUNT);      // TRG: Number of words to capture after trigger
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x308, ETR___INSTANCE_INDEX___SYNCCNT);            // Set PSCR
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x018, ETR___INSTANCE_INDEX___BUFFER_ADDRESS);     // Init RwP
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x014, ETR___INSTANCE_INDEX___BUFFER_ADDRESS);     // Init RRP
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x11C, ETR___INSTANCE_INDEX___BUFFER_ADDRESS_HI);  // Init DBAHI
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x118, ETR___INSTANCE_INDEX___BUFFER_ADDRESS);     // Init DBALO
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x004, ETR___INSTANCE_INDEX___BUFFER_SIZE);        // Init RSZ
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x110, ETR___INSTANCE_INDEX___AXI_CTL);            // Init AXICTL
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0xED0, ETR___INSTANCE_INDEX___AXI_CTL1);           // Init AXICTL1
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x03C, ETR___INSTANCE_INDEX___BUFFER_ADDRESS_HI);  // Init RWPHI
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x038, ETR___INSTANCE_INDEX___BUFFER_ADDRESS_HI);  // Init RRPHI
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000001);                                // Enable ETR
__ap = savedAP;

Message(0, "End CS_ETR___INSTANCE_INDEX___Capture_CircularBuffer @0x%08X, AP 0x%08X", ETR___INSTANCE_INDEX___ADDRESS, ETR___INSTANCE_INDEX___AP);

// Helper variables
__var savedAP     = __ap;
__var ffcrValue   = 0x00000000;
__var etrStatus   = 0x00000000;

Message(0, "Begin CS_ETR___INSTANCE_INDEX___Flush @0x%08X, AP 0x%08X", ETR___INSTANCE_INDEX___ADDRESS, ETR___INSTANCE_INDEX___AP);

__ap = ETR___INSTANCE_INDEX___AP;  // Set AP

// Flush the ETR formatter and stop capture.
ffcrValue = Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue &= ~(0x00001460);    // Clear FOnTrig, StopFl, FOnMan and TrigFl; do not insert a trigger packet on manual flush
ffcrValue |= 0x00001000;           // Stop after the manual flush completes
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
ffcrValue |= 0x00000040;           // Trigger manual flush
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);

// Disable ETR after flush until next run/step
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);
etrStatus = Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x00C);

// Helper variables
__var savedAP       = __ap;
__var etrStatus     = 0x00000000;
__var bufferSize    = 0x00000000;
__var readPointer   = 0x0000000000000000;
__var writePointer  = 0x0000000000000000;
__var bytesToRead   = 0x00000000;
__var bytesStreamed = 0x00000000;

Message(0, "Begin CS_ETR___INSTANCE_INDEX___Read_CircularBuffer @0x%08X, AP 0x%08X", ETR___INSTANCE_INDEX___ADDRESS, ETR___INSTANCE_INDEX___AP);
__ap = ETR___INSTANCE_INDEX___AP; // Set AP

// ETR RSZ is expressed in 32-bit words. RRP and RWP identify the valid capture range.
bufferSize   = Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x004) * 4;
etrStatus    = Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x00C);
readPointer  = Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x014) | (Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x038) << 32);
writePointer = Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x018) | (Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x03C) << 32);

control.block:
// STS.Full indicates that the circular buffer contains a complete capture.
bytesToRead = bufferSize;
// RWP identifies the oldest retained trace after the buffer wraps.
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x014, Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x018)); // Rebase RRP for chronological output
Write32(ETR___INSTANCE_INDEX___ADDRESS + 0x038, Read32(ETR___INSTANCE_INDEX___ADDRESS + 0x03C)); // Rebase RRPHI for chronological output

// Read through RRD, which advances RRP through the ETR trace memory.
BufferRead(0, 0, ETR___INSTANCE_INDEX___ADDRESS + 0x010, bytesToRead, 32);
// Stream to single unnamed trace buffer in system by default, insert name if multiple
// named buffers specified in PDSC. Decide which xxx_Read_Buffer sequence to call based
// on TraceBufferSelected().
bytesStreamed = BufferStreamOut(0, 0, bytesToRead, "", 1, 0);
Message(0, "Streamed %u of %u ETR trace bytes", bytesStreamed, bytesToRead);
